public Response<QueryReconRuleBySettleResponse> queryReconRuleBySettle(QueryReconRuleBySettleRequest request) {
        log.info("QueryReconRuleBySettleRequest:{}", JSON.toJSONString(request));
        Response<QueryReconRuleBySettleResponse> settleResponseResponse = new Response();
        QueryReconRuleBySettleResponse response = new QueryReconRuleBySettleResponse();
        try {
            ReconRuleConfigDo reconRuleConfigDo = reconRuleConfigDoTunnel.queryReconRuleBySettle(request.buildQueryMap());
            //结算单参数未匹配到对应的结算规则
            if (reconRuleConfigDo == null) {
                settleResponseResponse.setStatus(ResponseStatus.SUCCESS);
                settleResponseResponse.setRespCode(RespCodeEnum.NOT_QUERY_RECON_CONFIG.getCode());
                settleResponseResponse.setFailCause(RespCodeEnum.NOT_QUERY_RECON_CONFIG.getDesc());
                return settleResponseResponse;
            }
            //根据对账规则ID找到执行计划
            ReconExecPlanDo reconExecPlanDo = reconExecPlanDoTunnel.queryExecPlanBySettleOrderNo(request.getSettleOrderNo());

            //对账规则ID未找到对应的文件生成执行计划
            if (reconExecPlanDo == null) {
                //添加初始执行计划
                //TODO 与前端对其错误码
                reconExecPlanDoTunnel.insertReconExecPlan(buildReconExecPlanDo(request, reconRuleConfigDo));
                return Response.ofFailed(RespCodeEnum.WAIT_GENERATE.getCode(), RespCodeEnum.WAIT_GENERATE.getDesc());
            }
            //对账规则ID匹配到文件生成计划是否为执行完成
            if (!reconExecPlanDo.getFileMakeStatus().equals(ExecPlanStatusEnum.SUCCESS.getCode())) {
                return Response.ofFailed(RespCodeEnum.WAIT_GENERATE.getCode(), RespCodeEnum.WAIT_GENERATE.getDesc());
            }
            //根据ExecPlanId找到文件地址
            log.info("compSettleFileServerNo:{}", compSettleFileServerNo);
            FileServerDo fileServerDo = fileServerTunnelI.selectByFileServerNo(compSettleFileServerNo);

            String fileName = String.format(Constant.COM_SETTLE_FILE_NAME, reconRuleConfigDo.getReconOrgName(), reconRuleConfigDo.getReconObjectName(), reconExecPlanDo.getObjectNo(), "明细");
            log.info("fileName:{}", fileName);
            String keyPrefix = String.format(compReconFileFullPath, reconExecPlanDo.getExecPlanId(), fileName);
            String osskey = OSSUtils.getKeyByPrefix(fileServerDo.getUrl(),
                    fileServerDo.getUserName(), fileServerDo.getPassword(), keyPrefix, fileServerDo.getPort());
            log.info("osskey:{}", osskey);
            if (StringUtil.isEmpty(osskey)) {
                return Response.ofFailed(RespCodeEnum.WAIT_GENERATE.getCode(), RespCodeEnum.WAIT_GENERATE.getDesc());
            }

            String url = aliyunOssBucket.buildFileUrl(osskey, Boolean.FALSE);
            response.setObjectDetailUrl(url);
            response.setExecPlanId(reconExecPlanDo.getExecPlanId());
            response.setObjectNo(request.getSettleOrderNo());
        } catch (Exception e) {
            log.error("下载结算单异常! ", e);
            return Response.ofException("下载结算单异常", e.getMessage());
        }
        log.info("QueryReconRuleBySettleResponse:{}", JSON.toJSONString(response));
        return Response.ofSuccess(response);
    }

