public FileUrl buildFileUrl(String path, int fileSize, boolean isPublic) {
        String objectName = getObjectName(path);
        String url = buildUrl(objectName, isPublic);
        if (!supportThumbnail(objectName, fileSize)) {
            return new FileUrl(url);
        }
        String largeThumbUrl = buildThumbUrl(objectName, THUMB_LARGE_STYLE, isPublic);
        String middleThumbUrl = buildThumbUrl(objectName, THUMB_MIDDLE_STYLE, isPublic);
        String smallThumbUrl = buildThumbUrl(objectName, THUMB_SMALL_STYLE, isPublic);
        return new FileUrl(url, largeThumbUrl, middleThumbUrl, smallThumbUrl);
    }

public String buildUrl(String objectName, boolean isPublic) {
        if (isPublic) {
            return String.format(PUBLIC_URL_FORMAT, this.host, encodePath(objectName));
        }
        return buildSignedGetUrl(objectName, null,expiration);
    }

private String buildThumbUrl(String objectName, String style, boolean isPublic) {
        if (isPublic) {
            return String.format(PUBLIC_THUMB_URL_FORMAT, this.getHost(), encodePath(objectName), style);
        }
        return buildSignedGetUrl(objectName, style,expiration);
    }

private String buildSignedGetUrl(String objectName, String style,int expiration) {
        GeneratePresignedUrlRequest generatePresignedUrlRequest = new GeneratePresignedUrlRequest(this.getName(),
                objectName);
        if (StringUtils.isNotBlank(style)) {
            generatePresignedUrlRequest.setProcess(style);
        }
        generatePresignedUrlRequest.setMethod(HttpMethod.GET);

        generatePresignedUrlRequest.setExpiration(calculateUrlExpiration(expiration));
        URL url = getOssClient().generatePresignedUrl(generatePresignedUrlRequest);
        return url.toString().replace(url.getProtocol() + "://", "https://")
                .replace(url.getHost(), this.getHost());
    }

