@Override
    public Response<FileDownloadDTO> downloadTradeDetailFile(FileDownloadRequest fileDownloadRequest) {
        log.info("downloadTradeDetailFile 账户文件下载参数：{}", JSON.toJSONString(fileDownloadRequest));
        Response<FileDownloadDTO> response = new Response<>();
        response.setStatus(ResponseStatus.SUCCESS);
        try {
            if (fileDownloadRequest == null) {
                response.setRespCode(RespCodeEnum.PARAM_IS_NULL.getCode());
                response.setFailCause("参数不能为空");
                return response;
            }
            FileType fileType = fileDownloadRequest.getFileType();
            if (fileType == null) {
                response.setRespCode(RespCodeEnum.PARAM_IS_NULL.getCode());
                response.setFailCause("参数下载文件类型不能为空");
                return response;
            }
            String accountNo = fileDownloadRequest.getAccountNo();
            if (StringUtils.isEmpty(accountNo)) {
                response.setRespCode(RespCodeEnum.PARAM_IS_NULL.getCode());
                response.setFailCause("参数账号不能为空");
                return response;
            }

            if (fileType == FileType.ACCOUNT_FLOW) {
                Date tradeDate = fileDownloadRequest.getTradeDate();
                if (tradeDate == null) {
                    response.setRespCode(RespCodeEnum.PARAM_IS_NULL.getCode());
                    response.setFailCause("参数交易日期不能为空");
                    return response;
                }
                response = accountFlowFileDownloadComponent.downloadAccountFlowFile(accountNo, tradeDate, ReconCycleEnum.TODAY.getCode());
            } else if (fileType == FileType.ACCOUNT_FLOW_MONTH) {
                Date tradeDate = fileDownloadRequest.getTradeDate();
                if (tradeDate == null) {
                    response.setRespCode(RespCodeEnum.PARAM_IS_NULL.getCode());
                    response.setFailCause("参数交易日期不能为空");
                    return response;
                }
                //取月末日期
                Calendar calendar = Calendar.getInstance();
                calendar.setTime(tradeDate);
                calendar.add(Calendar.MONTH, 1);
                calendar.set(Calendar.DAY_OF_MONTH, 0);// 1为当月月初，0为上月月末

                response = accountFlowFileDownloadComponent.downloadAccountFlowFile(accountNo, calendar.getTime(), ReconCycleEnum.MONTH.getCode());
            }else if (fileType == FileType.RECEIVABLE) {
                Date tradeDate=new Date();
                response = accountReceivableFileComponent.downloadReceivableFile(accountNo,tradeDate);
            } else {
                response.setRespCode(RespCodeEnum.FILE_NOT_SUPPORT.getCode());
                response.setFailCause(RespCodeEnum.FILE_NOT_SUPPORT.getDesc());
            }
        } catch (Exception e) {
            log.error("请求参数：{},账户流水文件下载异常",JSON.toJSONString(fileDownloadRequest), e);
            response.setStatus(ResponseStatus.FAILED);
            response.setRespCode(RespCodeEnum.EXCEPTON.getCode());
        }
        log.info("账户流水文件下载参数：{},返回结果：{}", JSON.toJSONString(fileDownloadRequest),JSON.toJSONString(response));
        return response;
    }
